.section .rodata
manifest_prefix: .asciz "[package]\nname = \""
manifest_suffix: .asciz "\"\nversion = \"0.1.0\"\n\n[build]\nsource = \"src/main.s\"\ntarget = \"riscv64-linux\"\n"
